package vn.edu.hcmute.example3; import java.math.BigDecimal; import org.springframework.data.domain.*; import org.springframework.security.access.AccessDeniedException; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class ProductService {private final ProductRepository products; private final UserRepository users; ProductService(ProductRepository p,UserRepository u){products=p;users=u;} @Transactional(readOnly=true) Page<Product> page(String login,String q,int page,boolean admin){var user=users.findByUsernameOrEmail(login,login).orElseThrow(); var pageable=PageRequest.of(Math.max(0,page),6,Sort.by(Sort.Direction.DESC,"id")); return admin?products.findByNameContainingIgnoreCase(q,pageable):products.findByOwnerAndNameContainingIgnoreCase(user,q,pageable);} @Transactional Product save(Long id,String login,boolean admin,String name,String description,BigDecimal price,String image){if(price==null||price.signum()<0)throw new IllegalArgumentException("Giá bán không hợp lệ."); var owner=users.findByUsernameOrEmail(login,login).orElseThrow(); if(id==null)return products.save(new Product(name,description,price,image,owner)); var p=products.findOneById(id).orElseThrow(); check(p,owner,admin); p.update(name,description,price,image); return p;} @Transactional void delete(Long id,String login,boolean admin){var owner=users.findByUsernameOrEmail(login,login).orElseThrow(); var p=products.findOneById(id).orElseThrow(); check(p,owner,admin); products.delete(p);} @Transactional(readOnly=true) Product one(Long id,String login,boolean admin){var owner=users.findByUsernameOrEmail(login,login).orElseThrow();var p=products.findOneById(id).orElseThrow();check(p,owner,admin);return p;} private void check(Product p,AppUser u,boolean admin){if(!admin&&!p.getOwner().getId().equals(u.getId()))throw new AccessDeniedException("Không có quyền thao tác sản phẩm này.");}}
